def expected_value(num_eliminated):
    remaining = 4 - num_eliminated
    p_correct = 1 / remaining
    p_wrong = (remaining - 1) / remaining
    ev = p_correct * 3 + p_wrong * (-1)
    return ev

def should_guess(num_eliminated):
    return expected_value(num_eliminated) > 0

for k in range(4):
    print(f'Eliminated {k}: EV={expected_value(k):.4f}, Guess={should_guess(k)}')
